            return [
                [3 if grid[r][j] == grid[r][c + 1 + j] else
                 max(set(grid[r][:left_width]), key=grid[r][:left_width].count)
                 for j in range(left_width)]
                for r in range(h)
            ]

    for r in range(h):
        if len(set(grid[r])) == 1:
            top_height = r
            out = []
            for i in range(top_height):
                row = []
                for j in range(w):
                    if grid[i][j] == grid[r + 1 + i][j]:
                        row.append(3)
                    else:
                        vals = [grid[x][j] for x in range(top_height)]
                        row.append(max(set(vals), key=vals.count))
                out.append(row)
            return out

