def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []

    # Find an interior uniform separator, preferring the rare separator color.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            color = grid[r][0]
            freq = sum(v == color for row in grid for v in row)
            candidates.append((freq, abs(r - h / 2), "row", r))
    for c in range(1, w - 1):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            color = grid[0][c]
            freq = sum(v == color for row in grid for v in row)
            candidates.append((freq, abs(c - w / 2), "col", c))

    _, _, direction, index = min(candidates)

    if direction == "row":
        a, b = grid[:index], grid[index + 1:]
    else:
        a = [row[:index] for row in grid]
        b = [row[index + 1:] for row in grid]

    # The output uses the most common color shared at corresponding positions.
    counts = {}
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == b[r][c]:
                v = a[r][c]
                counts[v] = counts.get(v, 0) + 1
    color = max(counts, key=counts.get)

    return [
        [3 if a[r][c] == color and b[r][c] == color else color
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
